window.Cloud=(()=>{
 let client=null,user=null,writer=null,ready=false,remote=null,phase='loading',detail='',epoch=0,loadedAt=null;
 const cfg=window.VOLLEY_CONFIG||{},configured=!!(cfg.supabaseUrl&&cfg.supabaseKey);
 const el=id=>document.getElementById(id),text=(id,value)=>{if(el(id))el(id).textContent=value};
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const storageKey=()=>user?'volleyworld-user-'+user.id:KEY;
 function snapshot(){return JSON.parse(JSON.stringify(state))}
 function backup(){try{let items=JSON.parse(localStorage.getItem('volleyworld-backups')||'[]');items.unshift({time:new Date().toISOString(),account:user?.id||null,state:snapshot()});localStorage.setItem('volleyworld-backups',JSON.stringify(items.slice(0,5)))}catch{}}
 function apply(s){if(!validSave(s))throw Error('Tiến độ không hợp lệ.');state=JSON.parse(JSON.stringify(s));round=Math.max(0,state.rounds.findIndex(r=>r.some(m=>!m.sets)));try{localStorage.setItem(storageKey(),JSON.stringify(state))}catch{}render()}
 function summary(s){let n=s.rounds.flat().filter(m=>m.sets).length;return `${n}/496 trận league${s.bracket?' · Playoff':s.playin?' · Vé vớt':''}`}
 function status(p,message=''){phase=p;detail=typeof message==='string'?message:'';const labels={loading:'Đang kết nối…',local:'● Lưu trên thiết bị',choose:'⚠ Chọn tiến độ để đồng bộ',pending:'● Chờ đồng bộ',saving:'● Đang lưu online…',saved:'☁ Đã đồng bộ',conflict:'⚠ Có tiến độ từ thiết bị khác',error:'⚠ Chưa đồng bộ · bản máy đã giữ'};text('saved',labels[p]||labels.local);text('accountButton',user?'☁ Tài khoản':'☁ Đăng nhập');if(el('cloudDialog').open)draw()}
 function changed(s){if(!user||!writer)return;if(ready)writer.enqueue(s);else status(phase)}
 async function readRemote(){const {data,error}=await client.from('volleyworld_saves').select('state,revision,updated_at').eq('user_id',user.id).maybeSingle();if(error)throw error;if(data&&!validSave(data.state))throw Error('Tiến độ online không hợp lệ.');return data}
 function makeWriter(base){writer?.close();const uid=user.id,token=epoch;writer=new CloudWriter(async(payload,rev)=>{const {data,error}=await client.rpc('save_volleyworld',{p_state:payload,p_expected_revision:rev});if(error)throw Error(error.message);if(!Array.isArray(data)||!data[0])throw Error('Máy chủ chưa xác nhận lưu.');return data[0]},(p,result)=>{if(epoch!==token||user?.id!==uid)return;if(p==='conflict'){ready=false;status('conflict');void reviewConflict(token)}else if(p==='error'){ready=false;status('error','Không thể lưu online. Tiến độ trên thiết bị được giữ nguyên. Bạn có thể thử lại.')}else{if(p==='saved')loadedAt=result.updated_at;status(p)}});writer.activate(base);ready=true;}
 async function reviewConflict(token){try{const row=await readRemote();if(token!==epoch)return;remote=row;status('conflict');open()}catch{if(token===epoch)status('error','Không thể tải bản online. Hãy thử lại khi có mạng.')}}
 async function acceptOnline(){if(!remote)return;if(!confirm('Dùng tiến độ online? Bản trên máy sẽ được giữ trong bản sao khôi phục gần nhất.'))return;backup();apply(remote.state);loadedAt=remote.updated_at;makeWriter(remote.revision);status('saved');toast('Đã tải tiến độ online')}
 async function acceptLocal(){if(!client||!user||phase==='loading')return;if(remote&&!confirm('Đưa tiến độ thiết bị này lên thay bản online đang hiển thị?'))return;backup();const rev=remote?.revision||0;makeWriter(rev);writer.enqueue(snapshot());await writer.flush();}
 async function switchUser(next){if(next?.id===user?.id)return;epoch++;const token=epoch;writer?.close();writer=null;ready=false;remote=null;loadedAt=null;
 if(user){try{localStorage.setItem(storageKey(),JSON.stringify(state))}catch{}}
 user=next;
 if(!user){let guest;try{guest=JSON.parse(localStorage.getItem(KEY))}catch{}apply(guest&&validSave(guest)?guest:V.fresh());status('local');return}
 let candidate;try{candidate=JSON.parse(localStorage.getItem(storageKey()))}catch{}if(candidate&&validSave(candidate))apply(candidate);else {let guest;try{guest=JSON.parse(localStorage.getItem(KEY))}catch{}apply(guest&&validSave(guest)?guest:V.fresh())}
 status('loading');try{const row=await readRemote();if(token!==epoch)return;remote=row;if(row&&JSON.stringify(row.state)===JSON.stringify(state)){loadedAt=row.updated_at;makeWriter(row.revision);status('saved')}else{status('choose');open()}}catch{if(token===epoch){status('error','Đăng nhập thành công, nhưng chưa tải được tiến độ online. Hãy thử lại.');open()}}
 }
 async function retry(){if(!user)return;const token=epoch;status('loading');try{const row=await readRemote();if(token!==epoch)return;remote=row;if(row&&JSON.stringify(row.state)===JSON.stringify(state)){makeWriter(row.revision);loadedAt=row.updated_at;status('saved')}else{ready=false;writer?.close();writer=null;status('choose');open()}}catch{if(token===epoch)status('error','Chưa kết nối được. Tiến độ trên thiết bị vẫn được giữ.')}}
 async function syncNow(){if(!ready){await retry();return}writer.enqueue(snapshot());await writer.flush()}
 async function refresh(){if(!user||!ready||writer?.pending||writer?.running)return;const token=epoch;try{const row=await readRemote();if(token!==epoch||!ready)return;if(row&&row.revision!==writer.revision){ready=false;writer.close();remote=row;status('conflict');open()}}catch{/* Keep local play available; writes report connectivity failures. */}}
 function open(){draw();if(!el('cloudDialog').open)el('cloudDialog').showModal()}
 function draw(){const target=el('cloudContent');if(!configured){target.innerHTML='<p class="cloud-message">Lưu online đang được chuẩn bị. Bạn vẫn có thể chơi và lưu tiến độ trên thiết bị, hoặc xuất file để chuyển máy.</p>';return}if(!client){target.innerHTML=`<p class="cloud-message">${phase==='error'?'Chưa kết nối được dịch vụ đăng nhập. Kiểm tra mạng rồi tải lại trang.':'Đang kết nối dịch vụ đăng nhập…'}</p>`;return}if(!user){target.innerHTML=`<p class="cloud-message">Đăng nhập bằng liên kết gửi đến email để lưu cùng một giải trên nhiều thiết bị.</p><form id="loginForm"><label class="cloud-field">Email<input type="email" id="loginEmail" autocomplete="email" placeholder="ban@example.com" required></label><button class="primary" type="submit">Gửi liên kết đăng nhập</button></form><p id="loginMessage" class="cloud-message" role="status"></p>`;el('loginForm').onsubmit=login;return}
 const choose=phase==='choose'||phase==='conflict',needRetry=phase==='error';target.innerHTML=`<p class="cloud-message">Đã đăng nhập: <b>${esc(user.email)}</b></p>${choose?`<p class="cloud-message cloud-warn">${phase==='conflict'?'Tiến độ online đã thay đổi trên thiết bị khác.':'Chọn tiến độ để bắt đầu đồng bộ.'} Web sẽ không tự ghi đè hai bản.</p><div class="cloud-choice"><b>Bản trên thiết bị này</b><span class="cloud-message">${summary(state)}</span><br><button onclick="Cloud.acceptLocal()">Dùng bản này & lưu online</button></div>${remote?`<div class="cloud-choice"><b>Bản online</b><span class="cloud-message">${summary(remote.state)}<br>Cập nhật: ${esc(new Date(remote.updated_at).toLocaleString('vi-VN'))}</span><br><button class="primary" onclick="Cloud.acceptOnline()">Tiếp tục từ bản online</button></div>`:'<p class="cloud-message">Tài khoản chưa có tiến độ online. Chọn bản trên thiết bị để lưu lần đầu.</p>'}`:`<p class="cloud-message cloud-state">${esc(detail||({loading:'Đang tải tiến độ…',pending:'Đang chờ lưu tiến độ.',saving:'Đang lưu online…',saved:'Tiến độ đã đồng bộ.'}[phase]||'Tiến độ trên máy được giữ.'))}${loadedAt?'<br>Lần lưu online: '+esc(new Date(loadedAt).toLocaleString('vi-VN')):''}</p><div class="actions"><button class="primary" ${phase==='loading'?'disabled':''} onclick="Cloud.syncNow()">${needRetry?'Thử kết nối lại':'Lưu online ngay'}</button><button ${phase==='loading'?'disabled':''} onclick="Cloud.retry()">Kiểm tra bản online</button></div>`}<div class="actions" style="margin-top:20px"><button onclick="Cloud.restoreBackup()">Khôi phục bản trước</button><button onclick="Cloud.logout()">Đăng xuất</button></div><p class="cloud-message">Nếu mất mạng, tiến độ vẫn lưu trên thiết bị. Khi kết nối lại, bấm lưu online để tiếp tục đồng bộ.</p>`;}
 async function login(e){e.preventDefault();let email=el('loginEmail').value.trim(),button=e.target.querySelector('button');button.disabled=true;text('loginMessage','Đang gửi liên kết…');try{const {error}=await client.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin+location.pathname}});if(error)throw error;text('loginMessage','Kiểm tra email (cả thư rác) và mở liên kết đăng nhập. Nếu chưa nhận được, thử lại sau hoặc liên hệ chủ web.')}catch{text('loginMessage','Chưa gửi được email. Hãy kiểm tra địa chỉ hoặc thử lại sau.')}finally{button.disabled=false}}
 async function logout(){if(writer?.pending||phase==='saving'){if(!confirm('Một số tiến độ chưa đồng bộ. Bản trên thiết bị sẽ được giữ lại cho lần đăng nhập sau. Vẫn đăng xuất?'))return}ready=false;writer?.close();const {error}=await client.auth.signOut({scope:'local'});if(error){status('error','Chưa đăng xuất được. Hãy thử lại.');return}await switchUser(null);draw();toast('Đã đăng xuất. Tiến độ khách được khôi phục.')}
 function restoreBackup(){try{const items=JSON.parse(localStorage.getItem('volleyworld-backups')||'[]'),b=items.find(x=>x.account===(user?.id||null));if(!b||!validSave(b.state)){toast('Chưa có bản sao khôi phục cho tài khoản này.');return}if(!confirm('Khôi phục tiến độ trước đó ('+new Date(b.time).toLocaleString('vi-VN')+')?'))return;const restored=b.state;backup();apply(restored);save();draw();toast('Đã khôi phục bản trước')}catch{toast('Không đọc được bản sao khôi phục.')}}
 async function init(){if(!configured){status('local');return}try{const {createClient}=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm');client=createClient(cfg.supabaseUrl,cfg.supabaseKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});client.auth.onAuthStateChange((_event,session)=>setTimeout(()=>{void switchUser(session?.user||null)},0));const {data,error}=await client.auth.getSession();if(error)throw error;if(data.session)await switchUser(data.session.user);else status('local');}catch{status('error','Không kết nối được dịch vụ đăng nhập. Bạn vẫn chơi trên thiết bị được.')}}
 window.addEventListener('online',()=>{if(user)void retry()});window.addEventListener('focus',()=>void refresh());window.addEventListener('beforeunload',e=>{if(user&&(writer?.pending||writer?.running)){e.preventDefault();e.returnValue=''}});void init();
 return{open,changed,storageKey,acceptOnline,acceptLocal,retry,syncNow,logout,restoreBackup};
})();
